repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('ops', 58), ('ops', 44), ('web', 29), ('core', 12), ('core', 38), ('core', 40), ('web', 15)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

repo.journal.py:
"""A book of tickets with a cached total."""


class TicketBook:
    def __init__(self):
        self._tickets = []
        self._total = None

    def add(self, ticket):
        """Add one ticket to the book."""
        self._tickets.append(ticket)

    def total(self):
        """Return the total hours of the tickets in the book."""
        if self._total is None:
            self._total = sum(x.hours for x in self._tickets)
        return self._total

    def count(self):
        """Return how many tickets the book holds."""
        return len(self._tickets)


def describe_ticket(ticket):
    """Return a one-line description of a ticket."""
    return "%s: %s" % (ticket.team, ticket.hours)

